templates.home:
{{template "top" .}}<h1 style="margin:8px 0 0">{{.storeName}}</h1>{{with .tagline}}<p class="muted">{{.}}</p>{{end}}
<div class="chips"><a class="chip{{if not .category}} on{{end}}" href="/{{if eq .lang "ar"}}?lang=ar{{end}}">{{.t.all}}</a>{{range .categories}}<a class="chip{{if eq . $.category}} on{{end}}" href="/?c={{.}}{{if eq $.lang "ar"}}&lang=ar{{end}}">{{.}}</a>{{end}}</div>
<div class="grid">{{range .products}}<a class="card" href="/p/{{.id}}{{if eq $.lang "ar"}}?lang=ar{{end}}"><div class="img">{{if .image}}<img src="{{.image}}" alt="{{.name}}" loading="lazy">{{else}}{{.name}}{{end}}</div>
<div class="body"><div>{{.name}}</div><div class="price">AED {{.price}}</div>{{if le .stock 0}}<div class="muted">{{$.t.out_of_stock}}</div>{{end}}</div></a>{{end}}</div>
{{template "bottom" .}}

templates.product:
{{template "top" .}}{{with .product}}<div class="product"><div class="photo">{{if .image}}<img src="{{.image}}" alt="{{.name}}">{{else}}{{.name}}{{end}}</div>
<div><h1 style="margin-top:0">{{.name}}</h1><p class="price" style="font-size:22px">AED {{.price}}</p><p class="muted">{{$.t.vat_included}}</p><p>{{.description}}</p>
{{if gt .stock 0}}<div class="qty"><label for="qty" style="margin:0">{{$.t.quantity}}</label><input id="qty" type="number" min="1" max="{{.stock}}" value="1"></div>
<p><button id="add" data-id="{{.id}}" data-max="{{.stock}}">{{$.t.add_to_cart}}</button> <span id="added" class="ok" hidden>{{$.t.added}}</span></p>
{{else}}<p class="error">{{$.t.out_of_stock}}</p>{{end}}</div></div>{{end}}
<script>
var b=document.getElementById('add');if(b){b.addEventListener('click',function(){var id=Number(b.dataset.id),max=Number(b.dataset.max);
var q=Math.max(1,Math.min(max,Math.floor(Number(document.getElementById('qty').value)||1)));var c=rxCart(),f=null;
c.forEach(function(i){if(i.id===id)f=i});if(f){f.qty=Math.min(max,f.qty+q)}else{c.push({id:id,qty:q})}rxSave(c);document.getElementById('added').hidden=false})}
</script>{{template "bottom" .}}

templates.cart:
{{template "top" .}}<h1>{{.t.cart}}</h1>{{with .error}}<p class="error">{{.}}</p>{{end}}
<div id="empty" class="panel" hidden><p>{{.t.empty_cart}}</p><a class="btn" href="/{{if eq .lang "ar"}}?lang=ar{{end}}">{{.t.continue_shopping}}</a></div>
<div id="full" hidden><div class="panel" id="lines"></div>
<div class="panel"><div class="row"><span>{{.t.subtotal}}</span><span>AED <span id="subtotal"></span></span></div>
<div class="row"><span>{{.t.delivery}}</span><span id="delivery"></span></div><div class="row total"><span>{{.t.total}}</span><span>AED <span id="total"></span></span></div>
<p class="muted">{{.t.vat_included}} · {{.t.free_delivery_over}} AED {{.store.free_delivery_over}}</p></div>
<form class="panel" method="post" action="/checkout"><h2 style="margin-top:0">{{.t.checkout}}</h2>
<input type="hidden" name="cart" id="cart-field"><input type="hidden" name="lang" value="{{.lang}}">
{{if not .user}}<p><a class="btn" href="/_rx/auth/login?next=/cart{{if eq .lang "ar"}}%3Flang%3Dar{{end}}">{{.t.sign_in_to_checkout}}</a></p>{{else}}
<label for="name">{{.t.name}}</label><input id="name" name="name" autocomplete="name" required value="{{.user.name}}">
<label for="phone">{{.t.phone}}</label><input id="phone" name="phone" type="tel" autocomplete="tel" required value="{{.user.phone}}">
<label for="address">{{.t.address}}</label><textarea id="address" name="address" rows="2" autocomplete="street-address" required></textarea>
<label for="emirate">{{.t.emirate}}</label><select id="emirate" name="emirate" required><option>Dubai</option><option>Abu Dhabi</option><option>Sharjah</option><option>Ajman</option><option>Umm Al Quwain</option><option>Ras Al Khaimah</option><option>Fujairah</option></select>
<label>{{.t.payment}}</label>{{if .store.card_enabled}}<label style="display:flex;gap:8px;margin:6px 0"><input type="radio" name="payment" value="card" checked style="width:auto"> {{.t.pay_card}}</label>{{end}}
{{if .store.cod_enabled}}<label style="display:flex;gap:8px;margin:6px 0"><input type="radio" name="payment" value="cod"{{if not .store.card_enabled}} checked{{end}} style="width:auto"> {{.t.pay_cod}}</label>{{end}}
<p><button>{{.t.place_order}}</button></p>{{end}}</form></div>
<script>
(function(){var c=rxCart();if(!c.length){document.getElementById('empty').hidden=false;return}
fetch('/api/products?ids='+c.map(function(i){return i.id}).join(',')+'&lang={{.lang}}').then(function(r){return r.json()}).then(function(d){
var by={};d.products.forEach(function(p){by[p.id]=p});c=c.filter(function(i){return by[i.id]&&by[i.id].stock>0});
c.forEach(function(i){i.qty=Math.min(i.qty,by[i.id].stock)});rxSave(c);if(!c.length){document.getElementById('empty').hidden=false;return}
var box=document.getElementById('lines');box.textContent='';var sub=0;
c.forEach(function(i){var p=by[i.id];sub+=p.priceNum*i.qty;var row=document.createElement('div');row.className='row';
var left=document.createElement('span');left.textContent=p.name+' × '+i.qty;var right=document.createElement('span');right.textContent='AED '+(p.priceNum*i.qty).toFixed(2)+' ';
var rm=document.createElement('button');rm.className='secondary';rm.style.padding='2px 8px';rm.textContent='{{.t.remove}}';
rm.onclick=function(){rxSave(rxCart().filter(function(x){return x.id!==i.id}));location.reload()};right.appendChild(rm);row.appendChild(left);row.appendChild(right);box.appendChild(row)});
var del=sub>=d.free_delivery_over?0:d.delivery_fee;document.getElementById('subtotal').textContent=sub.toFixed(2);
document.getElementById('delivery').textContent=del?'AED '+del.toFixed(2):'{{.t.free}}';document.getElementById('total').textContent=(sub+del).toFixed(2);
document.getElementById('cart-field').value=JSON.stringify(c);document.getElementById('full').hidden=false})})();
