scripts.home:
function langOf(req) { return req.query.lang === 'ar' ? 'ar' : 'en'; }
function texts(lang) {
  const t = {};
  for (const r of db.query('SELECT key, en, ar FROM texts')) t[r.key] = (lang === 'ar' ? r.ar : r.en) || r.en;
  return t;
}
function store() { return db.query('SELECT * FROM store ORDER BY id LIMIT 1')[0]; }
function money(n) { return (Math.round(n * 100) / 100).toFixed(2); }
function page(req, extra) {
  const lang = langOf(req);
  const s = store();
  const base = {lang: lang, dir: lang === 'ar' ? 'rtl' : 'ltr', other: lang === 'ar' ? 'en' : 'ar', t: texts(lang), user: req.user,
    store: s, storeName: lang === 'ar' && s.name_ar ? s.name_ar : s.name, tagline: lang === 'ar' && s.tagline_ar ? s.tagline_ar : s.tagline,
    path: req.path, wa: (s.whatsapp || '').replace(/[^0-9]/g, '')};
  for (const k in extra) base[k] = extra[k];
  return base;
}
// Emails the buyer a confirmation in the order's language, and is quiet on failure.
function confirmOrder(o, link) {
  if (!o.email) return;
  const lang = o.lang === 'ar' ? 'ar' : 'en', t = texts(lang);
  const fill = (s) => s.replace(/\{id\}/g, o.id).replace(/\{store\}/g, lang === 'ar' && store().name_ar ? store().name_ar : store().name)
    .replace(/\{total\}/g, money(o.total)).replace(/\{payment\}/g, o.payment_method === 'cod' ? t.pay_cod : t.pay_card)
    .replace(/\{address\}/g, o.address).replace(/\{emirate\}/g, o.emirate).replace(/\{link\}/g, link);
  try { email.send({to: o.email, subject: fill(t.email_subject), text: fill(t.email_body)}); } catch (e) { console.warn('confirmation not sent: ' + e); }
}
function localize(p, lang) {
  return {id: p.id, name: lang === 'ar' && p.name_ar ? p.name_ar : p.name, description: lang === 'ar' && p.description_ar ? p.description_ar : p.description,
    category: p.category, price: money(p.price), priceNum: p.price, image: p.image, stock: p.stock};
}

// GET /?c=Category&lang=ar
function handle(req) {
  const lang = langOf(req);
  const c = req.query.c || '';
  const rows = c ? db.query('SELECT * FROM products WHERE active = 1 AND category = ? ORDER BY id', c)
                 : db.query('SELECT * FROM products WHERE active = 1 ORDER BY id');
  const cats = db.query('SELECT DISTINCT category FROM products WHERE active = 1 AND category IS NOT NULL AND category != \'\' ORDER BY category');
  return {template: 'home', data: page(req, {products: rows.map(p => localize(p, lang)), categories: cats.map(r => r.category), category: c})};
}

